#!/usr/bin/env node
// Execute data-bearing daily modules inside the isolated staged checkout.
// The parent process owns timeout/exit handling; this child cannot publish Git.
import { mkdir, readFile } from 'node:fs/promises';
import { resolve, join } from 'node:path';
import { writeJSONAtomic } from '../../lib/snapshot.mjs';
import { reviewLive, RULES } from './review-live.mjs';
import { reviewArtifact } from './gauntlet.mjs';

const [step, directory] = process.argv.slice(2);
if (!directory || !['live', 'benchmarks'].includes(step)) throw new Error('Usage: node ops/daily/phase-step.mjs live|benchmarks RUN_DIR');
const runDir = resolve(directory);
process.env.BH_WORKER_MAX_PRICE_PER_1M = '2';
process.env.BH_WORKER_REASONING_EFFORT = 'low';
process.env.BH_STATE = join(runDir, 'workers');
await mkdir(process.env.BH_STATE, { recursive: true });
try {
  let result;
  if (step === 'benchmarks') {
    const { refreshBenchmarks } = await import('./refresh-benchmarks.mjs');
    result = await refreshBenchmarks({ runDir });
    if (result?.ok !== true) throw new Error('Benchmark refresh reported failure');
  } else {
    const verified = await reviewLive({ runDir, rawDir: resolve('data/raw') });
    if (!verified?.ok || !verified.evidence?.manifest?.coverage?.complete) throw new Error('Live primary-source verification failed');
    const packets = verified.evidence.packets;
    const reviewed = [];
    let cursor = 0, failed = null;
    // Independent frozen batches can be reviewed concurrently. Each critic is
    // explicitly excluded from its own batch's recorded producer families.
    await Promise.all(Array.from({ length: 3 }, async () => {
      while (!failed && cursor < packets.length) {
        const packet = packets[cursor++];
        const rows = packet.rows.map((r) => ({ id: r.row_id, candidate: r.staged, locator: r.pointer, source: r.source }));
        const sources = packet.rows.map((r) => ({ ...r.source, locator: r.pointer,
          content: JSON.stringify({ row_id: r.row_id, primary_source_fields: r.extract }) }));
        const review = await reviewArtifact({ runDir, artifactId: `live-${packet.id}`, rows, sources,
          criteria: [
            { id: 'mapping', text: RULES[packet.dataset] },
            { id: 'values', text: 'For every row verify candidate fields against primary_source_fields. API passthrough/projection keeps exact numbers, units, identities and zero/null distinctions. Benchmark-only concepts do not apply to ordinary catalog or telemetry rows.' },
            { id: 'retention', text: 'Explicitly retained metadata keeps original dates; absent current fields must not create new values. Existing dated metadata is prior accepted evidence, not a newly measured value. New measurements require the supplied primary fields.' },
          ] });
        reviewed.push({ packet: packet.id, required_rows: rows.length, ...review });
        await writeJSONAtomic(join(runDir, 'reports', 'live-gauntlet-progress.json'), { total_packets: packets.length, reviewed });
        if (!review.accepted || review.fingerprints.length !== rows.length || review.quarantined.length) {
          failed = new Error(`Live gauntlet rejected ${packet.id}: ${review.errors.join('; ')}; ${review.quarantined.length} quarantined rows. Prior published snapshot remains unchanged.`);
          console.error(failed.message);
          break;
        }
        console.log(`live gauntlet ${packet.id}: ${rows.length} rows accepted (${reviewed.length}/${packets.length})`);
      }
    }));
    if (failed) throw failed;
    const covered = reviewed.reduce((n, r) => n + r.fingerprints.length, 0);
    if (covered !== verified.evidence.manifest.coverage.required_rows) throw new Error('Live gauntlet did not cover every source row');
    result = { ok: true, deterministic: verified.report, gauntlet: { packets: reviewed.length, rows_covered: covered, complete: true, reviews: reviewed.map((r) => ({ packet: r.packet, manifest: r.manifest })) } };
  }
  await writeJSONAtomic(join(runDir, 'reports', `${step}-step-result.json`), result);
  console.log(`${step} stage complete`);
} catch (error) {
  await writeJSONAtomic(join(runDir, 'reports', `${step}-step-result.json`), { ok: false, error: error.message });
  console.error(`DAILY ${step.toUpperCase()} FAILED: ${error.message}`);
  process.exitCode = 1;
}

